#!/bin/bash
# collect-status.sh — Run openclaw status --all --deep, parse output to JSON
# Parses: Overview table, Channels table, Agents table, Diagnosis section, gateway logs
# Timeout: 25s | Compatible: macOS (darwin) + Linux
set -uo pipefail

if ! command -v openclaw &>/dev/null; then
  echo '{"ran":false,"error":"openclaw CLI not found"}'
  exit 0
fi

# Capture full output (stdout + stderr merged, timeout guard)
raw_output=$(timeout 20 openclaw status --all --deep 2>&1) || true

# Try --json flag first (future-proofing)
json_output=$(timeout 20 openclaw status --all --deep --json 2>/dev/null) || json_output=""
if echo "$json_output" | node -e "const d=require('fs').readFileSync('/dev/stdin','utf8'); JSON.parse(d); process.exit(0);" 2>/dev/null; then
  # Structured JSON available — wrap with metadata and pass through
  echo "$json_output" | node -e "
    let d=''; process.stdin.on('data',c=>d+=c).on('end',()=>{
      const s = JSON.parse(d);
      console.log(JSON.stringify({ran:true,source:'json',timestamp:new Date().toISOString(),...s}, null, 2));
    });
  "
  exit 0
fi

# ─── Text output parsing via Node.js ─────────────────────────────────────────
echo "$raw_output" | node -e "
const readline = require('readline');
let raw = '';
process.stdin.on('data', c => raw += c);
process.stdin.on('end', () => {
  const lines = raw.split('\n');

  // ── Helpers ────────────────────────────────────────────────────────────────
  function isSeparator(line) {
    return /^[├┤┌┐└┘─┼┬┴╋═│\s]+$/.test(line.trim()) && line.includes('─');
  }
  function parseBoxRows(sectionLines) {
    // Returns array of cell arrays (one per data row, skipping separator rows)
    const rows = [];
    for (const line of sectionLines) {
      if (!line.includes('│')) continue;
      if (isSeparator(line)) continue;
      const cells = line.split('│').slice(1, -1).map(c => c.trim());
      if (cells.length > 0) rows.push(cells);
    }
    return rows;
  }

  // ── Section detection ──────────────────────────────────────────────────────
  const sections = { header: [], overview: [], channels: [], agents: [], diagnosis: [] };
  let currentSection = 'header';

  for (const line of lines) {
    const t = line.trim();
    if (t === 'Overview')            { currentSection = 'overview';  continue; }
    if (t === 'Channels')            { currentSection = 'channels';  continue; }
    if (t === 'Agents')              { currentSection = 'agents';    continue; }
    if (t.startsWith('Diagnosis'))   { currentSection = 'diagnosis'; continue; }
    sections[currentSection].push(line);
  }

  // ── Parse header (version + commit) ───────────────────────────────────────
  const headerText = sections.header.join(' ');
  const versionMatch = headerText.match(/OpenClaw\s+([0-9]+\.[0-9]+[^\s(]*)/);
  const commitMatch  = headerText.match(/\(([0-9a-f]{6,})\)/);
  const version = versionMatch ? versionMatch[1] : null;
  const commit  = commitMatch  ? commitMatch[1]  : null;

  // ── Parse Overview table ───────────────────────────────────────────────────
  const overviewRows = parseBoxRows(sections.overview);
  const overviewMap = {};
  // First row is header (Item, Value) — skip it
  for (let i = 1; i < overviewRows.length; i++) {
    const [key, ...rest] = overviewRows[i];
    if (key) overviewMap[key.trim()] = rest.join(' │ ').trim();
  }

  // Extract structured fields from Overview values
  function parseGateway(raw) {
    if (!raw) return {};
    const latencyMatch = raw.match(/reachable\s+(\d+)ms/);
    const authMatch    = raw.match(/auth\s+(\w+)/);
    const bindMatch    = raw.match(/\(([^)]+)\)/);
    const urlMatch     = raw.match(/(wss?:\/\/[^\s]+)/);
    return {
      raw,
      url:         urlMatch    ? urlMatch[1]    : null,
      bind:        bindMatch   ? bindMatch[1]   : null,
      latency_ms:  latencyMatch ? parseInt(latencyMatch[1]) : null,
      auth_type:   authMatch   ? authMatch[1]   : null
    };
  }
  function parseService(raw) {
    if (!raw) return { installed: false, running: false };
    const pidMatch = raw.match(/pid\s+(\d+)/);
    return {
      installed: raw.includes('installed') && !raw.includes('not installed'),
      loaded:    raw.includes('loaded'),
      running:   raw.includes('running'),
      pid:       pidMatch ? parseInt(pidMatch[1]) : null,
      raw
    };
  }
  function parseAgentsOverview(raw) {
    if (!raw) return {};
    const totalMatch   = raw.match(/(\d+)\s+total/);
    const bootMatch    = raw.match(/(\d+)\s+bootstrapping/);
    const activeMatch  = raw.match(/(\d+)\s+active/);
    const sessionMatch = raw.match(/(\d+)\s+session/);
    return {
      total:         totalMatch   ? parseInt(totalMatch[1])   : 0,
      bootstrapping: bootMatch    ? parseInt(bootMatch[1])    : 0,
      active:        activeMatch  ? parseInt(activeMatch[1])  : 0,
      sessions:      sessionMatch ? parseInt(sessionMatch[1]) : 0
    };
  }

  const gwRaw = overviewMap['Gateway'] || '';
  const overview = {
    version:         overviewMap['Version']         || null,
    os:              overviewMap['OS']               || null,
    node:            overviewMap['Node']             || null,
    config_path:     overviewMap['Config']           || null,
    dashboard:       overviewMap['Dashboard']        || null,
    tailscale:       overviewMap['Tailscale']        || 'unknown',
    tailscale_on:    (overviewMap['Tailscale'] || '').toLowerCase() !== 'off',
    update_channel:  overviewMap['Channel']          || null,
    update_status:   overviewMap['Update']           || null,
    gateway:         parseGateway(gwRaw),
    security_note:   overviewMap['Security']         || null,
    gateway_self:    overviewMap['Gateway self']     || null,
    gateway_service: parseService(overviewMap['Gateway service']),
    node_service:    parseService(overviewMap['Node service']),
    agents_overview: parseAgentsOverview(overviewMap['Agents'])
  };

  // Is update available? If update_status contains a higher version, flag it
  const updateRaw = overview.update_status || '';
  const latestMatch = updateRaw.match(/latest\s+([0-9]+\.[0-9]+[^\s]*)/);
  overview.latest_version = latestMatch ? latestMatch[1] : null;
  overview.up_to_date = !latestMatch ||
    (overview.version && latestMatch[1] === overview.version);

  // ── Parse Channels table ───────────────────────────────────────────────────
  const channelRows = parseBoxRows(sections.channels);
  const channels = [];
  if (channelRows.length > 1) {
    // Row 0 = headers: Channel, Enabled, State, Detail
    for (let i = 1; i < channelRows.length; i++) {
      const r = channelRows[i];
      if (r[0]) channels.push({
        name:    r[0] || '',
        enabled: (r[1] || '').toLowerCase() === 'true' || r[1] === '✓',
        state:   r[2] || '',
        detail:  r[3] || ''
      });
    }
  }

  // ── Parse Agents table ─────────────────────────────────────────────────────
  const agentRows = parseBoxRows(sections.agents);
  const agents = [];
  if (agentRows.length > 1) {
    // Headers: Agent, Bootstrap file, Sessions, Active, Store
    for (let i = 1; i < agentRows.length; i++) {
      const r = agentRows[i];
      if (r[0]) agents.push({
        name:              r[0] || '',
        bootstrap_file:    r[1] || '',
        bootstrap_present: r[1] !== 'ABSENT' && r[1] !== '' && r[1] !== 'none',
        sessions:          parseInt(r[2]) || 0,
        active_since:      r[3] || '',
        store_path:        (r[4] || '').replace(/^~/, process.env.HOME || '~')
      });
    }
  }

  // ── Parse Diagnosis section ────────────────────────────────────────────────
  const checks = [];
  const logLines = [];
  const logIssues = [];
  let inLogs = false;
  let skillsEligible = 0, skillsMissing = 0;

  for (const line of sections.diagnosis) {
    const t = line.trim();

    // Log section detection
    if (t.startsWith('Gateway logs') || t.startsWith('# stderr') || t.startsWith('# stdout')) {
      inLogs = true;
    }

    if (inLogs) {
      // Collect notable log lines (errors, warnings, timeouts)
      if (t.match(/timeout|ENOENT|error|timed out|LLM|failed|ENOENT|command not found/i)) {
        const redacted = t.replace(/(token|secret|password|api.?key)[^\s]*/gi, '[REDACTED]');
        logLines.push(redacted);
        if (logLines.length <= 20) logIssues.push(redacted);
      }
      continue;
    }

    // Check lines
    if (t.startsWith('✓') || t.startsWith('!') || t.startsWith('·')) {
      const status = t.startsWith('✓') ? 'ok' : t.startsWith('!') ? 'warn' : 'info';
      const rest = t.slice(1).trim();
      const colonIdx = rest.indexOf(':');
      const label  = colonIdx >= 0 ? rest.slice(0, colonIdx).trim() : rest;
      const detail = colonIdx >= 0 ? rest.slice(colonIdx + 1).trim() : '';

      // Extract skills count
      if (label === 'Skills') {
        const em = detail.match(/(\d+)\s+eligible/);
        const mm = detail.match(/(\d+)\s+missing/);
        if (em) skillsEligible = parseInt(em[1]);
        if (mm) skillsMissing  = parseInt(mm[1]);
      }

      checks.push({ status, label, detail });
    }
  }

  // ── Assemble output ────────────────────────────────────────────────────────
  const result = {
    ran:       true,
    source:    'text',
    timestamp: new Date().toISOString(),
    version,
    commit,
    overview,
    channels,
    agents,
    diagnosis: {
      checks,
      skills_eligible: skillsEligible,
      skills_missing:  skillsMissing,
      config_valid:    checks.some(c => c.label === 'Config' && c.status === 'ok'),
      port_conflicts:  checks.filter(c => c.label.startsWith('Port') && c.status === 'warn').map(c => c.detail),
      tailscale_issue: checks.some(c => c.label === 'Tailscale' && c.status === 'warn'),
      channel_issues:  checks.some(c => c.label.startsWith('Channel') && c.status === 'warn')
    },
    log_issues: logIssues
  };

  console.log(JSON.stringify(result, null, 2));
});
"

#!/bin/bash
# collect-tools.sh — Check MCP tools and CLI tools availability, output JSON
# Checks: MCP tools (memory_search, file_read, bash, etc.) + CLI tools (clawhub, openclaw, node, curl)
# Timeout: 10s | Compatible: macOS (darwin) + Linux
set -euo pipefail

OPENCLAW_HOME="${OPENCLAW_HOME:-$HOME/.openclaw}"
OPENCLAW_CONFIG_PATH="${OPENCLAW_CONFIG_PATH:-$OPENCLAW_HOME/openclaw.json}"

node <<'NODESCRIPT'
const fs = require("fs");
const { execSync } = require("child_process");

const HOME = process.env.OPENCLAW_HOME || (process.env.HOME + "/.openclaw");
const CONFIG = process.env.OPENCLAW_CONFIG_PATH || (HOME + "/openclaw.json");

const result = {
  timestamp: new Date().toISOString(),
  cli_tools: [],
  mcp_tools: [],
  summary: {
    cli_total: 0, cli_available: 0, cli_missing: 0,
    mcp_total: 0, mcp_available: 0, mcp_missing: 0,
    core_missing: []
  },
  issues: []
};

// --- 1. CLI Tools Check ---
const cliTools = [
  { name: "node",     core: true,  check: "node --version" },
  { name: "curl",     core: true,  check: "curl --version" },
  { name: "bash",     core: true,  check: "bash --version" },
  { name: "clawhub",  core: false, check: "clawhub --version", anyOf: "openclaw" },
  { name: "openclaw", core: false, check: "openclaw --version", anyOf: "clawhub" },
  { name: "git",      core: false, check: "git --version" },
  { name: "jq",       core: false, check: "jq --version" },
  { name: "sendmail", core: false, check: "which sendmail" }
];

for (const tool of cliTools) {
  const entry = { name: tool.name, core: tool.core, available: false, version: null };
  try {
    const out = execSync(tool.check, { timeout: 5000, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }).trim();
    entry.available = true;
    // Extract version string (first line, first version-like match)
    const verMatch = out.match(/v?(\d+\.\d+[\.\d]*)/);
    if (verMatch) entry.version = verMatch[0];
  } catch {}
  result.cli_tools.push(entry);
}

// Check anyOf pairs (clawhub OR openclaw)
const clawhubAvail = result.cli_tools.find(t => t.name === "clawhub")?.available;
const openclawAvail = result.cli_tools.find(t => t.name === "openclaw")?.available;
if (!clawhubAvail && !openclawAvail) {
  result.issues.push({ type: "cli", severity: "error", msg: "Neither clawhub nor openclaw CLI found — at least one is required" });
  result.summary.core_missing.push("clawhub|openclaw");
}

// --- 2. MCP Tools Check ---
// MCP tools are registered via OpenClaw config tools section
// We check if the config declares them and if the tools endpoint is reachable
const mcpTools = [
  { name: "memory_search", core: true,  description: "Search agent memory" },
  { name: "memory_inject",  core: true,  description: "Inject knowledge into memory" },
  { name: "file_read",     core: true,  description: "Read files from filesystem" },
  { name: "file_write",    core: false, description: "Write files to filesystem" },
  { name: "bash",          core: true,  description: "Execute shell commands" },
  { name: "web_fetch",     core: false, description: "Fetch web content" },
  { name: "web_search",    core: false, description: "Search the web" },
  { name: "skill_invoke",  core: false, description: "Invoke other skills" }
];

// Check config for tools profile
let toolsProfile = "unknown";
let configuredTools = [];
if (fs.existsSync(CONFIG)) {
  try {
    const raw = fs.readFileSync(CONFIG, "utf8");
    const clean = raw.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
    const config = JSON.parse(clean);
    toolsProfile = config.tools?.profile || "default";
    configuredTools = config.tools?.enabled || [];

    // If tools section has MCP server config
    if (config.tools?.mcp) {
      const mcpConfig = config.tools.mcp;
      for (const [server, serverConf] of Object.entries(mcpConfig)) {
        if (serverConf.tools) {
          configuredTools.push(...serverConf.tools);
        }
      }
    }
  } catch {}
}

// Check MCP tools availability via Gateway API (if reachable)
let gatewayTools = null;
try {
  const port = 18789;
  const out = execSync(
    `curl -s --connect-timeout 3 --max-time 5 http://localhost:${port}/tools 2>/dev/null`,
    { timeout: 6000, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }
  );
  if (out) {
    try {
      const parsed = JSON.parse(out);
      gatewayTools = Array.isArray(parsed) ? parsed.map(t => t.name || t) :
                     parsed.tools ? parsed.tools.map(t => t.name || t) : null;
    } catch {}
  }
} catch {}

for (const tool of mcpTools) {
  const entry = {
    name: tool.name,
    core: tool.core,
    description: tool.description,
    configured: configuredTools.includes(tool.name),
    available: false
  };

  // If we got gateway tools list, check against it
  if (gatewayTools) {
    entry.available = gatewayTools.includes(tool.name);
  } else {
    // Assume available if configured or profile is full/coding
    entry.available = entry.configured || ["full", "coding"].includes(toolsProfile);
  }

  result.mcp_tools.push(entry);
}

// --- 3. Summary ---
result.summary.cli_total = result.cli_tools.length;
result.summary.cli_available = result.cli_tools.filter(t => t.available).length;
result.summary.cli_missing = result.summary.cli_total - result.summary.cli_available;

result.summary.mcp_total = result.mcp_tools.length;
result.summary.mcp_available = result.mcp_tools.filter(t => t.available).length;
result.summary.mcp_missing = result.summary.mcp_total - result.summary.mcp_available;

// Check for missing core tools
for (const t of result.cli_tools) {
  if (t.core && !t.available) {
    result.summary.core_missing.push(t.name);
    result.issues.push({ type: "cli", severity: "error", msg: "Core CLI tool missing: " + t.name });
  }
}
for (const t of result.mcp_tools) {
  if (t.core && !t.available) {
    result.summary.core_missing.push(t.name);
    result.issues.push({ type: "mcp", severity: "error", msg: "Core MCP tool missing: " + t.name });
  }
}

// Non-core missing → warnings
for (const t of [...result.cli_tools, ...result.mcp_tools]) {
  if (!t.core && !t.available) {
    result.issues.push({ type: t.version !== undefined ? "cli" : "mcp", severity: "warning", msg: "Optional tool missing: " + t.name });
  }
}

result.tools_profile = toolsProfile;
result.gateway_tools_reachable = gatewayTools !== null;

console.log(JSON.stringify(result, null, 2));
NODESCRIPT

#!/bin/bash
# collect-workspace-audit.sh — Workspace audit: critical md files, storage usage,
# config cross-validation, environment variable audit
# Output: JSON to stdout | Timeout: 10s | Compatible: macOS (darwin) + Linux
set -euo pipefail

OPENCLAW_HOME="${OPENCLAW_HOME:-$HOME/.openclaw}"
OPENCLAW_CONFIG_PATH="${OPENCLAW_CONFIG_PATH:-$OPENCLAW_HOME/openclaw.json}"

node <<'NODESCRIPT'
const fs = require("fs");
const path = require("path");

const HOME = process.env.OPENCLAW_HOME || (process.env.HOME + "/.openclaw");
const CONFIG = process.env.OPENCLAW_CONFIG_PATH || (HOME + "/openclaw.json");

const result = {
  timestamp: new Date().toISOString(),
  critical_files: { present: [], missing: [], total_checked: 0 },
  storage: { directories: {}, total_size_mb: 0 },
  config_cross_validation: { issues: [] },
  env_audit: { defined: [], missing: [], conflicts: [] },
  summary: { issues_found: 0, severity_breakdown: { critical: 0, warning: 0, info: 0 } }
};

// --- 1. Critical File Presence ---
const criticalFiles = [
  { path: CONFIG, name: "openclaw.json", required: true },
  { path: HOME + "/config", name: "config/", required: false, isDir: true },
  { path: HOME + "/logs", name: "logs/", required: true, isDir: true },
  { path: HOME + "/skills", name: "skills/", required: true, isDir: true },
  { path: HOME + "/data", name: "data/", required: true, isDir: true },
  { path: HOME + "/reports", name: "reports/", required: false, isDir: true },
  { path: HOME + "/plugins", name: "plugins/", required: false, isDir: true },
  { path: HOME + "/workspace", name: "workspace/", required: false, isDir: true }
];

for (const cf of criticalFiles) {
  result.critical_files.total_checked++;
  const exists = fs.existsSync(cf.path);
  if (exists) {
    result.critical_files.present.push({ name: cf.name, path: cf.path.replace(process.env.HOME, "~"), required: cf.required });
  } else {
    result.critical_files.missing.push({ name: cf.name, path: cf.path.replace(process.env.HOME, "~"), required: cf.required });
    if (cf.required) {
      result.summary.severity_breakdown.warning++;
    }
  }
}

// --- 2. Storage Usage ---
function getDirSize(dirPath) {
  let totalSize = 0;
  let fileCount = 0;
  try {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      const fp = path.join(dirPath, entry.name);
      try {
        if (entry.isFile()) {
          totalSize += fs.statSync(fp).size;
          fileCount++;
        } else if (entry.isDirectory() && !entry.name.startsWith(".")) {
          const sub = getDirSize(fp);
          totalSize += sub.size;
          fileCount += sub.files;
        }
      } catch {}
    }
  } catch {}
  return { size: totalSize, files: fileCount };
}

const storageDirs = ["config", "skills", "logs", "data", "plugins", "memory", "workspace", "reports"];
let totalBytes = 0;

for (const dir of storageDirs) {
  const dirPath = path.join(HOME, dir);
  if (fs.existsSync(dirPath)) {
    const info = getDirSize(dirPath);
    result.storage.directories[dir] = {
      size_mb: Math.round(info.size / 1024 / 1024 * 100) / 100,
      file_count: info.files,
      exists: true
    };
    totalBytes += info.size;
  } else {
    result.storage.directories[dir] = { size_mb: 0, file_count: 0, exists: false };
  }
}
result.storage.total_size_mb = Math.round(totalBytes / 1024 / 1024 * 100) / 100;

// Flag large directories
for (const [dir, info] of Object.entries(result.storage.directories)) {
  if (info.size_mb > 500) {
    result.config_cross_validation.issues.push({
      type: "large_directory",
      severity: "warning",
      directory: dir,
      size_mb: info.size_mb,
      msg: dir + "/ is " + info.size_mb + " MB — consider cleanup"
    });
  }
}

// --- 3. Config Cross-Validation ---
try {
  if (fs.existsSync(CONFIG)) {
    const raw = fs.readFileSync(CONFIG, "utf8");
    const clean = raw.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
    const config = JSON.parse(clean);

    // Check agent workspace dir exists
    const workspace = config.agents?.defaults?.workspace;
    if (workspace && !fs.existsSync(workspace.replace("$HOME", process.env.HOME))) {
      result.config_cross_validation.issues.push({
        type: "config_path_mismatch",
        severity: "warning",
        msg: "Configured agent workspace does not exist: " + workspace
      });
    }

    // Check gateway bind mode (security)
    const bind = config.gateway?.bind || "loopback";
    if (bind === "lan" || bind === "tailnet") {
      result.config_cross_validation.issues.push({
        type: "gateway_exposed",
        severity: "info",
        msg: "Gateway bind set to '" + bind + "' — accessible beyond localhost"
      });
    }

    // Check heartbeat config
    if (config.agents?.heartbeat) {
      if (!config.agents.heartbeat.autoRecovery) {
        result.config_cross_validation.issues.push({
          type: "no_auto_recovery",
          severity: "warning",
          msg: "Agent heartbeat autoRecovery is disabled"
        });
      }
    }

    // maxConcurrent vs available skills
    const skillsDir = HOME + "/skills/@botlearn";
    let skillCount = 0;
    try {
      skillCount = fs.readdirSync(skillsDir).filter(d => !d.startsWith(".")).length;
    } catch {}
    const maxConc = config.agents?.defaults?.maxConcurrent || 3;
    if (skillCount > 0 && maxConc > skillCount * 3) {
      result.config_cross_validation.issues.push({
        type: "over_provisioned_concurrency",
        severity: "info",
        msg: "maxConcurrent (" + maxConc + ") seems high for " + skillCount + " installed skills"
      });
    }

    // Timeout sanity — agents.defaults.timeoutSeconds
    const timeout = config.agents?.defaults?.timeoutSeconds || 600;
    if (timeout > 3600) {
      result.config_cross_validation.issues.push({
        type: "excessive_timeout",
        severity: "warning",
        msg: "Agent timeout " + timeout + "s (>1h) is very high"
      });
    }
  }
} catch {}

// --- 4. Environment Variable Audit ---
const envVars = [
  { name: "OPENCLAW_HOME", required: false, default: "~/.openclaw" },
  { name: "OPENCLAW_CONFIG_PATH", required: false, default: "$OPENCLAW_HOME/openclaw.json" },
  { name: "OPENCLAW_STATE_DIR", required: false, default: "$OPENCLAW_HOME/state" },
  { name: "OPENCLAW_LOG_DIR", required: false, default: "$OPENCLAW_HOME/logs" },
  { name: "OPENCLAW_SKILLS_DIR", required: false, default: "$OPENCLAW_HOME/skills" }
];

for (const ev of envVars) {
  const value = process.env[ev.name];
  if (value) {
    result.env_audit.defined.push({ name: ev.name, set: true, value_redacted: value.replace(process.env.HOME, "~") });
    // Check if defined path exists
    if (!fs.existsSync(value)) {
      result.env_audit.conflicts.push({
        name: ev.name,
        severity: "warning",
        msg: ev.name + " points to non-existent path: " + value.replace(process.env.HOME, "~")
      });
    }
  } else {
    result.env_audit.missing.push({ name: ev.name, default: ev.default, required: ev.required });
  }
}

// Check for conflicting env vars
if (process.env.OPENCLAW_HOME && process.env.OPENCLAW_CONFIG_PATH) {
  const expectedPrefix = process.env.OPENCLAW_HOME;
  if (!process.env.OPENCLAW_CONFIG_PATH.startsWith(expectedPrefix)) {
    result.env_audit.conflicts.push({
      name: "OPENCLAW_CONFIG_PATH",
      severity: "warning",
      msg: "OPENCLAW_CONFIG_PATH is outside OPENCLAW_HOME directory"
    });
  }
}

// --- Aggregate issues ---
result.summary.issues_found =
  result.critical_files.missing.filter(f => f.required).length +
  result.config_cross_validation.issues.length +
  result.env_audit.conflicts.length;

for (const issue of result.config_cross_validation.issues) {
  result.summary.severity_breakdown[issue.severity] = (result.summary.severity_breakdown[issue.severity] || 0) + 1;
}
for (const conflict of result.env_audit.conflicts) {
  result.summary.severity_breakdown[conflict.severity] = (result.summary.severity_breakdown[conflict.severity] || 0) + 1;
}

console.log(JSON.stringify(result, null, 2));
NODESCRIPT

#!/bin/bash
# deliver-report.sh — Multi-channel report delivery
# Usage:
#   deliver-report.sh --input <scored-report.json> [--channel terminal|browser|slack|dingtalk|feishu|discord|email|auto]
#   deliver-report.sh --input <scored-report.json> --md <report.md> --html <report.html> [--channel auto]
# Timeout: 15s | Compatible: macOS (darwin) + Linux
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
OPENCLAW_HOME="${OPENCLAW_HOME:-$HOME/.openclaw}"
CHANNEL_CONFIG="${OPENCLAW_HOME}/config/doctor-channels.json"

INPUT=""
MD_FILE=""
HTML_FILE=""
CHANNEL=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --input)   INPUT="$2"; shift 2 ;;
    --md)      MD_FILE="$2"; shift 2 ;;
    --html)    HTML_FILE="$2"; shift 2 ;;
    --channel) CHANNEL="$2"; shift 2 ;;
    *) shift ;;
  esac
done

if [[ -z "$INPUT" || ! -f "$INPUT" ]]; then
  echo '{"error":"--input <scored-report.json> required"}' >&2
  exit 1
fi

node -e '
const fs = require("fs");
const { execSync } = require("child_process");
const path = require("path");

const report = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
const mdFile = process.argv[2] || "";
const htmlFile = process.argv[3] || "";
const requestedChannel = process.argv[4] || "";
const channelConfigPath = process.argv[5];
const scriptDir = process.argv[6];

// Load channel config
let config = {
  default_channel: "terminal",
  channels: {
    terminal: { enabled: true },
    browser: { enabled: true, auto_open_on_macos: true }
  }
};
try {
  if (fs.existsSync(channelConfigPath)) {
    config = JSON.parse(fs.readFileSync(channelConfigPath, "utf8"));
  }
} catch {}

// Determine channels to deliver to
let channels = [];
if (requestedChannel && requestedChannel !== "auto") {
  channels = [requestedChannel];
} else {
  // Auto mode: deliver to all enabled channels
  for (const [name, ch] of Object.entries(config.channels || {})) {
    if (ch.enabled) channels.push(name);
  }
  if (channels.length === 0) channels = ["terminal"];
}

function statusEmoji(score) {
  if (score >= 80) return "✅";
  if (score >= 60) return "⚠️";
  if (score >= 40) return "🟡";
  return "🔴";
}

// Redact secrets from payload before sending
function redactSecrets(text) {
  return text.replace(
    /(?:api[_-]?key|apikey|secret|client_secret|token|access_token|bearer|password|passwd|pwd)\s*[:=]\s*["'"'"']?[A-Za-z0-9_\-\.]{8,}/gi,
    (match) => match.replace(/[:=]\s*["'"'"']?[A-Za-z0-9_\-\.]{8,}/, "= ***REDACTED***")
  );
}

const cs = report.category_scores || {};
const results = [];

for (const channel of channels) {
  try {
    switch (channel) {
      case "terminal": {
        // Output MD to terminal
        if (mdFile && fs.existsSync(mdFile)) {
          const md = fs.readFileSync(mdFile, "utf8");
          process.stderr.write(md + "\n");
        } else {
          const dims = Object.entries(cs).map(([k, v]) =>
            k.substring(0, 4).toUpperCase() + " " + statusEmoji(v.score) + " " + v.score
          ).join(" | ");
          process.stderr.write(
            "🏥 OpenClaw Health: " + report.overall_score + "/100 " + statusEmoji(report.overall_score) + "\n" +
            dims + "\n" +
            "⚡ " + ((report.issue_summary?.critical || 0) + (report.issue_summary?.high || 0)) + " issues need attention\n"
          );
        }
        results.push({ channel: "terminal", status: "delivered" });
        break;
      }

      case "browser": {
        if (htmlFile && fs.existsSync(htmlFile)) {
          const openScript = path.join(scriptDir, "open-report.sh");
          const autoOpen = config.channels?.browser?.auto_open_on_macos !== false;
          const os = process.platform;
          if (os === "darwin" && autoOpen) {
            try {
              execSync("bash " + JSON.stringify(openScript) + " " + JSON.stringify(htmlFile), { timeout: 5000 });
              results.push({ channel: "browser", status: "opened" });
            } catch {
              results.push({ channel: "browser", status: "failed", error: "Could not open browser" });
            }
          } else {
            results.push({ channel: "browser", status: "skipped", reason: "Not macOS or auto_open disabled", file: htmlFile });
          }
        } else {
          results.push({ channel: "browser", status: "skipped", reason: "No HTML report file" });
        }
        break;
      }

      case "slack": {
        const webhook = config.channels?.slack?.webhook_url;
        if (!webhook) { results.push({ channel: "slack", status: "skipped", reason: "No webhook_url" }); break; }
        const issues = (report.issues || []).slice(0, 5);
        const issuesMd = issues.map((i, idx) => (idx+1) + ". " + i.severity.toUpperCase() + " [" + i.id + "] " + i.msg).join("\\n");
        const payload = JSON.stringify({
          blocks: [
            { type: "header", text: { type: "plain_text", text: "🏥 OpenClaw Health Report" } },
            { type: "section", fields: [
              { type: "mrkdwn", text: "*Score:* " + report.overall_score + "/100 " + statusEmoji(report.overall_score) },
              { type: "mrkdwn", text: "*Status:* " + report.overall_status }
            ]},
            { type: "section", text: { type: "mrkdwn", text: issuesMd || "No issues found" } }
          ]
        });
        const safe = redactSecrets(payload);
        execSync("curl -sS -X POST -H \"Content-Type: application/json\" -d " + JSON.stringify(safe) + " " + JSON.stringify(webhook), { timeout: 10000 });
        results.push({ channel: "slack", status: "delivered" });
        break;
      }

      case "dingtalk": {
        const webhook = config.channels?.dingtalk?.webhook_url;
        if (!webhook) { results.push({ channel: "dingtalk", status: "skipped", reason: "No webhook_url" }); break; }
        const issues = (report.issues || []).slice(0, 5);
        const issuesMd = issues.map((i, idx) => (idx+1) + ". " + i.severity + " [" + i.id + "] " + i.msg).join("\\n");
        const payload = JSON.stringify({
          msgtype: "markdown",
          markdown: {
            title: "🏥 OpenClaw 健康报告",
            text: "# 🏥 OpenClaw 健康报告\\n\\n**分数: " + report.overall_score + "/100** " + statusEmoji(report.overall_score) + "\\n\\n" + issuesMd
          }
        });
        const safe = redactSecrets(payload);
        execSync("curl -sS -X POST -H \"Content-Type: application/json\" -d " + JSON.stringify(safe) + " " + JSON.stringify(webhook), { timeout: 10000 });
        results.push({ channel: "dingtalk", status: "delivered" });
        break;
      }

      case "feishu": {
        const webhook = config.channels?.feishu?.webhook_url;
        if (!webhook) { results.push({ channel: "feishu", status: "skipped", reason: "No webhook_url" }); break; }
        const templateColor = report.overall_score >= 80 ? "green" : report.overall_score >= 60 ? "yellow" : report.overall_score >= 40 ? "orange" : "red";
        const payload = JSON.stringify({
          msg_type: "interactive",
          card: {
            header: {
              title: { tag: "plain_text", content: "🏥 OpenClaw 健康报告" },
              template: templateColor
            },
            elements: [
              { tag: "div", fields: [
                { is_short: true, text: { tag: "lark_md", content: "**总分**\\n" + report.overall_score + "/100" } },
                { is_short: true, text: { tag: "lark_md", content: "**状态**\\n" + report.overall_status } }
              ]}
            ]
          }
        });
        const safe = redactSecrets(payload);
        execSync("curl -sS -X POST -H \"Content-Type: application/json\" -d " + JSON.stringify(safe) + " " + JSON.stringify(webhook), { timeout: 10000 });
        results.push({ channel: "feishu", status: "delivered" });
        break;
      }

      case "discord": {
        const webhook = config.channels?.discord?.webhook_url;
        if (!webhook) { results.push({ channel: "discord", status: "skipped", reason: "No webhook_url" }); break; }
        const colorMap = { healthy: 2280667, warning: 15379208, elevated: 16348950, critical: 15614020 };
        const fields = Object.entries(cs).map(([k, v]) => ({
          name: k.charAt(0).toUpperCase() + k.slice(1),
          value: statusEmoji(v.score) + " " + v.score + "/100",
          inline: true
        }));
        const payload = JSON.stringify({
          embeds: [{
            title: "🏥 OpenClaw Health Report",
            description: "Score: **" + report.overall_score + "/100** · Status: **" + report.overall_status + "**",
            color: colorMap[report.overall_status] || 2280667,
            fields: fields,
            footer: { text: "@botlearn/botlearn-healthcheck v3.0.0" },
            timestamp: report.timestamp
          }]
        });
        const safe = redactSecrets(payload);
        execSync("curl -sS -X POST -H \"Content-Type: application/json\" -d " + JSON.stringify(safe) + " " + JSON.stringify(webhook), { timeout: 10000 });
        results.push({ channel: "discord", status: "delivered" });
        break;
      }

      case "email": {
        const emailConf = config.channels?.email;
        if (!emailConf?.to) { results.push({ channel: "email", status: "skipped", reason: "No recipient" }); break; }
        const subject = (emailConf.subject_prefix || "[OpenClaw Doctor]") + " Health Report — " + report.overall_score + "/100 " + report.overall_status;
        const from = emailConf.from || "OpenClaw Doctor <noreply@localhost>";
        const htmlContent = htmlFile && fs.existsSync(htmlFile) ? fs.readFileSync(htmlFile, "utf8") : "<p>Score: " + report.overall_score + "/100</p>";
        const safeHtml = redactSecrets(htmlContent);
        const emailPayload = "From: " + from + "\\nTo: " + emailConf.to + "\\nSubject: " + subject + "\\nContent-Type: text/html; charset=UTF-8\\n\\n" + safeHtml;
        const tmpFile = "/tmp/doctor-email-" + Date.now() + ".eml";
        fs.writeFileSync(tmpFile, emailPayload);
        try {
          const host = emailConf.smtp_host || "localhost";
          const port = emailConf.smtp_port || 25;
          execSync("sendmail -t < " + JSON.stringify(tmpFile) + " 2>/dev/null || curl --url smtp://" + host + ":" + port + " --mail-from " + JSON.stringify(from) + " --mail-rcpt " + JSON.stringify(emailConf.to) + " --upload-file " + JSON.stringify(tmpFile), { timeout: 10000 });
          results.push({ channel: "email", status: "delivered", to: emailConf.to });
        } catch {
          results.push({ channel: "email", status: "failed", error: "sendmail/smtp delivery failed" });
        }
        try { fs.unlinkSync(tmpFile); } catch {}
        break;
      }

      default:
        results.push({ channel, status: "unknown_channel" });
    }
  } catch (e) {
    results.push({ channel, status: "error", error: e.message });
  }
}

console.log(JSON.stringify({ delivered: results, total_channels: results.length }, null, 2));
' "$INPUT" "$MD_FILE" "$HTML_FILE" "$CHANNEL" "$CHANNEL_CONFIG" "$SCRIPT_DIR"

#!/bin/bash
# generate-report.sh — Generate MD and/or HTML reports from analysis JSON
# v4.0: Adapted for 10-dimension traffic-light model
# Usage:
#   generate-report.sh --input <analysis.json> --format md|html|all [--output-dir <dir>]
# Timeout: 10s | Compatible: macOS (darwin) + Linux
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
SKILL_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
TEMPLATE="$SKILL_DIR/assets/report-template.html"

INPUT=""
FORMAT="md"
OUTPUT_DIR=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --input)  INPUT="$2"; shift 2 ;;
    --format) FORMAT="$2"; shift 2 ;;
    --output-dir) OUTPUT_DIR="$2"; shift 2 ;;
    *) shift ;;
  esac
done

if [[ -z "$INPUT" || ! -f "$INPUT" ]]; then
  echo "Usage: generate-report.sh --input <analysis.json> --format md|html|all [--output-dir <dir>]" >&2
  exit 1
fi

if [[ -z "$OUTPUT_DIR" ]]; then
  OUTPUT_DIR="$(dirname "$INPUT")"
fi
mkdir -p "$OUTPUT_DIR"

# --- Generate Markdown Report ---
generate_md() {
  node -e '
const fs = require("fs");
const analysis = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
const outDir = process.argv[2];

const statusIcon = { pass: "✅", warning: "⚠️", error: "❌" };
const dims = analysis.dimensions || [];
const summary = analysis.summary || {};

const lines = [];

// L0 — One-line status
const overallIcon = statusIcon[analysis.overall_status] || "❓";
lines.push(`# 🏥 OpenClaw Health Report v4.0`);
lines.push("");
lines.push(`> **${summary.pass_count || 0}✅ ${summary.warning_count || 0}⚠️ ${summary.error_count || 0}❌** — Status: **${analysis.overall_status}** ${overallIcon}`);
lines.push(`> Generated: ${analysis.timestamp}`);
lines.push("");

// L1 — Dimension grid
lines.push("## Dimension Status");
lines.push("");
const row1 = dims.slice(0, 5).map(d => `${d.label} ${statusIcon[d.status] || "❓"}`).join(" | ");
const row2 = dims.slice(5, 10).map(d => `${d.label} ${statusIcon[d.status] || "❓"}`).join(" | ");
lines.push("```");
lines.push(row1);
lines.push(row2);
lines.push("```");
lines.push("");

// Dimension detail table
lines.push("## All Dimensions");
lines.push("");
lines.push("| # | Status | Dimension | Message |");
lines.push("|---|--------|-----------|---------|");
for (const d of dims) {
  lines.push(`| ${d.id} | ${statusIcon[d.status]} | ${d.label} (${d.label_en}) | ${d.message} |`);
}
lines.push("");

// L2 — Issues (only ⚠️ and ❌)
const problemDims = dims.filter(d => d.status !== "pass");
if (problemDims.length > 0) {
  lines.push("## Issues");
  lines.push("");
  lines.push("| # | Status | Dimension | Issue | Fix Reference |");
  lines.push("|---|--------|-----------|-------|---------------|");
  let idx = 0;
  for (const d of problemDims) {
    for (const issue of (d.issues || []).filter(i => i.severity !== "info")) {
      idx++;
      const fixRef = issue.fix_ref ? "`" + issue.fix_ref + "`" : "—";
      lines.push(`| ${idx} | ${statusIcon[d.status]} | ${d.label} | ${issue.msg} | ${fixRef} |`);
    }
  }
  lines.push("");
  lines.push("> 💡 Run \\`clawhub doctor --fix\\` to auto-fix issues");
  lines.push("");
}

// All pass celebration
if (problemDims.length === 0) {
  lines.push("## ✅ All Clear!");
  lines.push("");
  lines.push("All 10 dimensions passed. Your OpenClaw installation is healthy.");
  lines.push("");
}

lines.push("---");
lines.push("*Generated by @botlearn/botlearn-healthcheck v4.0.0*");

const md = lines.join("\n");
const outPath = outDir + "/report.md";
fs.writeFileSync(outPath, md);
console.log(outPath);
' "$INPUT" "$OUTPUT_DIR"
}

# --- Generate HTML Report ---
generate_html() {
  node -e '
const fs = require("fs");
const analysis = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
const templatePath = process.argv[2];
const outDir = process.argv[3];

const statusIcon = { pass: "✅", warning: "⚠️", error: "❌" };
const statusColor = { pass: "#22c55e", warning: "#eab308", error: "#ef4444" };
const statusClass = { pass: "text-green", warning: "text-yellow", error: "text-red" };

let html = "";
// Try to use template, or generate standalone HTML
if (fs.existsSync(templatePath)) {
  html = fs.readFileSync(templatePath, "utf8");
}

const dims = analysis.dimensions || [];
const summary = analysis.summary || {};

// Build dimension grid HTML
const gridItems = dims.map(d => {
  const color = statusColor[d.status] || "#94a3b8";
  const icon = statusIcon[d.status] || "❓";
  return `<div class="dim-card" style="border-left:4px solid ${color}">
    <div class="dim-status">${icon}</div>
    <div class="dim-label">${d.label}</div>
    <div class="dim-msg" style="color:${color}">${d.message}</div>
  </div>`;
}).join("\n");

// Build issue rows
const problemDims = dims.filter(d => d.status !== "pass");
const issueRows = [];
let idx = 0;
for (const d of problemDims) {
  for (const issue of (d.issues || []).filter(i => i.severity !== "info")) {
    idx++;
    const color = statusColor[d.status] || "#94a3b8";
    issueRows.push(`<tr><td>${idx}</td><td style="color:${color}">${statusIcon[d.status]}</td><td>${d.label}</td><td>${issue.msg}</td><td>${issue.fix_ref || "—"}</td></tr>`);
  }
}

// Generate standalone HTML if template not available
const overallColor = statusColor[analysis.overall_status] || "#94a3b8";
const generatedHtml = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>🏥 OpenClaw Health Report</title>
  <style>
    :root { --bg: #0f172a; --fg: #e2e8f0; --card: #1e293b; --muted: #94a3b8; --green: #22c55e; --yellow: #eab308; --red: #ef4444; }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: var(--bg); color: var(--fg); padding: 2rem; max-width: 1200px; margin: 0 auto; }
    h1 { font-size: 1.8rem; margin-bottom: 1rem; }
    .overall { text-align: center; padding: 2rem; background: var(--card); border-radius: 12px; margin-bottom: 2rem; }
    .overall-status { font-size: 3rem; font-weight: 700; color: ${overallColor}; }
    .overall-summary { font-size: 1.2rem; color: var(--muted); margin-top: 0.5rem; }
    .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; margin-bottom: 2rem; }
    .dim-card { background: var(--card); padding: 1rem; border-radius: 8px; }
    .dim-status { font-size: 1.5rem; }
    .dim-label { font-weight: 600; margin: 0.3rem 0; }
    .dim-msg { font-size: 0.85rem; }
    table { width: 100%; border-collapse: collapse; background: var(--card); border-radius: 8px; overflow: hidden; }
    th, td { padding: 0.75rem 1rem; text-align: left; border-bottom: 1px solid #334155; }
    th { background: #334155; font-weight: 600; }
    .text-green { color: var(--green); } .text-yellow { color: var(--yellow); } .text-red { color: var(--red); }
    .footer { text-align: center; color: var(--muted); margin-top: 2rem; font-size: 0.85rem; }
    @media print { body { background: white; color: black; } .dim-card, table, .overall { background: #f8fafc; } }
  </style>
</head>
<body>
  <h1>🏥 OpenClaw Health Report</h1>
  <div class="overall">
    <div class="overall-status">${statusIcon[analysis.overall_status]} ${analysis.overall_status?.toUpperCase()}</div>
    <div class="overall-summary">${summary.pass_count || 0}✅ ${summary.warning_count || 0}⚠️ ${summary.error_count || 0}❌ — ${analysis.timestamp || ""}</div>
  </div>
  <h2>Dimensions</h2>
  <div class="grid">${gridItems}</div>
  ${issueRows.length > 0 ? "<h2>Issues</h2><table><tr><th>#</th><th>Status</th><th>Dimension</th><th>Issue</th><th>Fix</th></tr>" + issueRows.join("") + "</table>" : "<h2>✅ All Clear!</h2><p>All 10 dimensions passed.</p>"}
  <div class="footer">Generated by @botlearn/botlearn-healthcheck v4.0.0</div>
</body>
</html>`;

const outPath = outDir + "/report.html";
fs.writeFileSync(outPath, generatedHtml);
console.log(outPath);
' "$INPUT" "$TEMPLATE" "$OUTPUT_DIR"
}

# --- Main ---
case "$FORMAT" in
  md)
    MD_PATH=$(generate_md)
    echo "{\"format\":\"md\",\"path\":\"$MD_PATH\"}"
    ;;
  html)
    HTML_PATH=$(generate_html)
    echo "{\"format\":\"html\",\"path\":\"$HTML_PATH\"}"
    ;;
  all)
    MD_PATH=$(generate_md)
    HTML_PATH=$(generate_html)
    echo "{\"format\":\"all\",\"md\":\"$MD_PATH\",\"html\":\"$HTML_PATH\"}"
    ;;
  *)
    echo "Unknown format: $FORMAT. Use md, html, or all." >&2
    exit 1
    ;;
